select energy_manager.load_cards($cards$[
{"id":"p4-b08-021","paper":4,"topic":"Compressor Performance","kind":"problem","front":"The compressor draws 100 kW and the measured FAD is 1407.6 m³/hr. Find the specific power requirement.","back":"About 0.071 kW per m³/hr.","explain":"Specific power is actual power consumed divided by measured FAD. A lower value means less energy per unit of air delivered, so it is a benchmark for the plant.","flash":false,"source":"BEE Book 4 Ch 08 p157","steps":[{"prompt":"Write the formula.","answer":"Specific power = actual power consumed / measured FAD","explain":"Chapter definition."},{"prompt":"Substitute.","answer":"100 / 1407.6","explain":"kW divided by m³/hr."},{"prompt":"Evaluate.","answer":"= 0.071 kW per m³/hr","explain":"Compare this value with the design or standard figure for the plant."}],"order":4363},
{"id":"p4-b08-022","paper":4,"topic":"Compressor Performance","kind":"fact","front":"In the compressor displacement formula, what does S stand for and what are the other terms?","back":"S = 1 for single-acting cylinders and 2 for double-acting cylinders. Displacement = π/4 × D² × L × S × N × n, where D is bore, L stroke, N speed in rpm and n the number of cylinders.","explain":"A double-acting cylinder sweeps volume on both strokes, so it gives twice the displacement per revolution. Use metres for D and L to get m³/min.","flash":false,"source":"BEE Book 4 Ch 08 p156","order":4364},
{"id":"p4-b08-023","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A compressor has a 16.88 m³/min piston displacement and a 14.75 m³/min rating at 7 kg/cm². The pump-up test uses a total storage volume of 8.322 m³, filling from 0.5 to 7.03 kg/cm² in 4.021 min with atmospheric pressure 1.026 kg/cm² (a). Find the output and the shortfall against rating.","back":"Output 13.17 m³/min; shortfall 1.577 m³/min, which is 10.69% below the 14.75 m³/min rating. The compressor needs further investigation.","explain":"Output = (P₂ − P₁) × V / (Pa × t). A shortfall of this size points to a compressor fault, not measurement noise.","flash":false,"source":"BEE Book 4 Ch 08 p159","steps":[{"prompt":"Find the pressure rise.","answer":"7.03 − 0.5 = 6.53 kg/cm²","explain":"The rise from initial to final pressure."},{"prompt":"Compute the output.","answer":"(6.53 × 8.322) / (1.026 × 4.021) = 13.17 m³/min","explain":"Atmospheric pressure and the pump-up time are in the denominator, as in the book's working."},{"prompt":"Compare with the rating.","answer":"14.75 − 13.17 = 1.577 m³/min, i.e. 10.69% short","explain":"A shortfall of this size is the trigger for further investigation."}],"order":4365},
{"id":"p4-b08-024","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A 340 m³/hr reciprocating compressor is loaded 80% of the time: 32 kW when loaded and 7 kW when unloaded. After leakage is fixed, the loaded time falls to 60%. Find the annual energy saving at 6000 h/yr.","back":"Average saving 5 kW; annual saving 30,000 kWh.","explain":"Average power = loaded fraction × loaded power + unloaded fraction × unloaded power. Fixing leaks cuts the loaded time, which cuts the average power.","flash":false,"source":"BEE Book 4 Ch 08 p159","steps":[{"prompt":"Find the average power at 80% loading.","answer":"0.8 × 32 + 0.2 × 7 = 27 kW","explain":"Time-weighted average of loaded and unloaded power."},{"prompt":"Find the average power at 60% loading.","answer":"0.6 × 32 + 0.4 × 7 = 22 kW","explain":"Same method with the new loaded fraction."},{"prompt":"Find the saving in power.","answer":"27 − 22 = 5 kW","explain":"Average power saved."},{"prompt":"Find the annual saving.","answer":"5 × 6000 = 30,000 kWh/yr","explain":"Multiply by operating hours per year."}],"order":4366},
{"id":"p4-b08-025","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A compressed air discharge temperature is 55 °C, which is 15 °C above the 40 °C ambient. What correction factor applies to the FAD?","back":"Factor = (273 + 40) / (273 + 55) = 0.954, applied to the measured FAD.","explain":"Hot discharge air is less dense than ambient air, so the free air figure is reduced. The chapter prints the ratio in the other order, so check the direction when applying it.","flash":false,"source":"BEE Book 4 Ch 08 p160","steps":[{"prompt":"Find the discharge temperature.","answer":"40 + 15 = 55 °C","explain":"The discharge is 15 °C above ambient."},{"prompt":"Compute the ratio of absolute temperatures.","answer":"(273 + 40) / (273 + 55) = 313 / 328","explain":"Both temperatures are converted to kelvin."},{"prompt":"Evaluate.","answer":"= 0.954","explain":"Multiply the measured FAD by 0.954 to get the corrected figure."}],"order":4367},
{"id":"p4-b08-026","paper":4,"topic":"Compressor Performance","kind":"fact","front":"Which parameters influence the isothermal power requirement of compressed air?","back":"Absolute intake pressure, free air delivered, and the compression ratio (through its natural log).","explain":"From P_iso = P₁ × Q × ln r / 36.7. Higher intake pressure, higher flow or higher compression ratio each increase the isothermal power.","flash":false,"source":"BEE Book 4 Ch 08 p160","order":4368},
{"id":"p4-b08-027","paper":4,"topic":"Compressor Performance","kind":"fact","front":"What is free air delivery (FAD)?","back":"The volume of air a compressor delivers, measured at ambient (free air) conditions, per unit time.","explain":"FAD is the actual output that the nozzle and pump-up tests measure. It is the basis for isothermal power and specific power.","flash":false,"source":"BEE Book 4 Ch 08 p160","order":4369},
{"id":"p4-b08-028","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A compressor has isothermal efficiency 63%, intake pressure 1.03 kg/cm² (a), rated flow 340 m³/hr and shaft power 25 kW. Find the delivery pressure.","back":"About 5.37 kg/cm² (a).","explain":"Isothermal power = 0.63 × 25 = 15.75 kW. Solving the isothermal power formula gives a compression ratio of about 5.21, so P₂ = 5.21 × 1.03 ≈ 5.37 kg/cm² (a).","flash":false,"source":"BEE Book 4 Ch 08 p160","steps":[{"prompt":"Find the isothermal power.","answer":"0.63 × 25 = 15.75 kW","explain":"Isothermal efficiency times shaft power."},{"prompt":"Rearrange the formula for ln r.","answer":"ln r = 15.75 × 36.7 / (1.03 × 340) = 1.651","explain":"From P_iso = P₁ × Q × ln r / 36.7."},{"prompt":"Find the compression ratio.","answer":"r = e^1.651 = 5.21","explain":"Inverse natural log."},{"prompt":"Find the delivery pressure.","answer":"P₂ = 5.21 × 1.03 = 5.37 kg/cm² (a)","explain":"Compression ratio times absolute intake pressure."}],"order":4370},
{"id":"p4-b08-029","paper":4,"topic":"Compressor Performance","kind":"problem","front":"A 1680 m³/hr compressor is tested by pump-up. Receiver 10 m³, interconnecting pipe 1 m³, initial and inlet pressure 1.0 kg/cm² (a), final 8.25 kg/cm² (a), filled in 3 minutes. Receiver air is at 40 °C and inlet air at 30 °C. Find the operating FAD in m³/min and m³/hr.","back":"About 26.6 m³/min (1595 m³/hr) before temperature correction; about 25.7 m³/min (1544 m³/hr) after correcting to inlet conditions, roughly 92% of the 1680 m³/hr rating.","explain":"The pump-up formula gives the volume delivered. Hot receiver air is corrected to inlet conditions by 303/313. The corrected figure is about 8% below the rating, which is worth investigating.","flash":false,"source":"BEE Book 4 Ch 08 p161","steps":[{"prompt":"Find the storage volume.","answer":"10 + 1 = 11 m³","explain":"Receiver plus interconnecting pipe."},{"prompt":"Find the FAD before temperature correction.","answer":"(8.25 − 1.0) × 11 / (1.0 × 3) = 26.58 m³/min = 1595 m³/hr","explain":"Pump-up formula with atmospheric pressure 1.0 kg/cm² (a) and 3 minutes."},{"prompt":"Correct for temperature.","answer":"26.58 × 303 / 313 = 25.73 m³/min = 1544 m³/hr","explain":"Receiver air at 40 °C against 30 °C inlet; the hotter air occupies more volume."},{"prompt":"Compare with the rating.","answer":"1544 / 1680 ≈ 92%","explain":"About 8% below the rated flow."}],"order":4371},
{"id":"p4-b08-030","paper":4,"topic":"Compressor Performance","kind":"problem","front":"Loaded for 40 min of each hour at 150 kW and unloaded for 20 min at 45 kW. Energy costs Rs 5/kWh. Find the energy cost per day of 24-hour operation.","back":"About Rs 13,800 per day.","explain":"The hourly average is 115 kW, so 115 kWh per hour. Over 24 hours that is 2,760 kWh per day, at Rs 5 per kWh.","flash":false,"source":"BEE Book 4 Ch 08 p161","steps":[{"prompt":"Find the average power per hour.","answer":"(40/60) × 150 + (20/60) × 45 = 100 + 15 = 115 kW","explain":"Time-weighted average of loaded and unloaded power."},{"prompt":"Find the energy per day.","answer":"115 × 24 = 2,760 kWh","explain":"Hourly average times 24 hours."},{"prompt":"Find the cost per day.","answer":"2,760 × Rs 5 = Rs 13,800","explain":"Multiply by the energy price."}],"order":4372},
{"id":"p4-b08-031","paper":4,"topic":"Compressor Performance","kind":"problem","front":"Unloading is cut to 10 min and loading rises to 50 min each hour, with 120 kW loaded and 35 kW unloaded. Operation is 8000 h/yr at Rs 5/kWh, and the pulley and belts cost Rs 40,000. Find the hourly average power, the annual saving and the payback period.","back":"Average 105.8 kW, a saving of about 9.2 kWh per hour (from 115 kW), about Rs 3.67 lakh per year, and payback of about 0.11 years (about 1.3 months).","explain":"The saving is the hourly difference in average power, multiplied by 8000 h and Rs 5. The pulley cost is small against the annual saving, so payback is short.","flash":false,"source":"BEE Book 4 Ch 08 p161","steps":[{"prompt":"Find the hourly average power after the change.","answer":"(50/60) × 120 + (10/60) × 35 = 100 + 5.83 = 105.8 kW","explain":"Time-weighted average with the new loading split."},{"prompt":"Find the hourly saving.","answer":"115 − 105.8 = 9.2 kWh","explain":"Compare with the 115 kW average before the change."},{"prompt":"Find the annual saving.","answer":"9.17 × 8000 = 73,333 kWh; × Rs 5 = Rs 3.67 lakh","explain":"Multiply by operating hours and the tariff."},{"prompt":"Find the payback.","answer":"40,000 / 3,66,667 = 0.11 year, about 1.3 months","explain":"Payback = cost / annual saving."}],"order":4373},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is one ton of refrigeration (1 TR) in terms of ice?","back":"The cooling obtained when one ton of ice melts in one day.","explain":"Tons of refrigeration is the unit used for the cooling capacity of chillers and air conditioners. Every TR figure in the performance test, and the kW/TR rating, is based on this unit.","flash":true,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-001","paper":4,"order":4374},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is the net refrigerating capacity of a chiller?","back":"The mass flow rate of evaporator water multiplied by the enthalpy difference between water entering and leaving the cooler, expressed in kcal/h or TR. It is the actual operating TR.","explain":"Net refrigerating capacity is what the chiller really delivers under the conditions at the time of the test. In the field it is found as flow times temperature difference times specific heat of water.","flash":false,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-002","paper":4,"order":4375},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What does kW/ton measure, and is a higher or lower value better?","back":"kW/ton is the compressor motor power input divided by the tons of cooling produced. A lower kW/ton means a more efficient plant.","explain":"kW/ton is often called efficiency, but strictly it is power input per unit of cooling. Because it is an input-per-output ratio, the lower the number the better.","flash":true,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-003","paper":4,"order":4376},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is the Coefficient of Performance (COP) of a chiller or heat pump?","back":"Useful heat output divided by electrical input, in the same units. A heat pump giving 5 kW of heat from 1 kW of electrical input has a COP of 5.0.","explain":"COP is dimensionless because output and input use the same units. The book's example is in heating terms; for a cooling chiller the output is the refrigeration effect. A higher COP means more efficient operation.","flash":false,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-004","paper":4,"order":4377},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is the Energy Efficiency Ratio (EER), and which programme uses this definition?","back":"EER is the cooling capacity in watts divided by the power input in watts at full-load conditions. The BEE star labelling programme uses this definition. The higher the EER, the more efficient the unit.","explain":"EER is measured at full load, so it describes rated efficiency. The book's example: 4000 W (1.14 TR) of cooling from 1000 W of input gives an EER of 4.0.","flash":true,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-005","paper":4,"order":4378},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is the purpose of an HVAC performance test?","back":"To verify the refrigeration system's performance using field measurements: measure net cooling capacity (TR) and energy requirement at actual operating conditions, then compare energy use at actual load with design conditions.","explain":"Field measurement shows what the plant actually delivers, which may differ from design. The gap between actual and design values shows where energy is being wasted.","flash":false,"source":"BEE Book 4 Ch 09 p165","id":"p4-b09-006","paper":4,"order":4379},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What is the EER of a unit giving 13,648 Btu/h (1.14 TR) of cooling from 1000 W of electrical input, when cooling is in Btu/h?","back":"EER = 13.65 (Btu/h of cooling per watt of input).","explain":"EER can be stated with cooling in Btu/h over watts of input. The same unit has an EER of 4.0 on a watt-to-watt basis, so check which basis a rating uses before comparing units.","flash":false,"source":"BEE Book 4 Ch 09 p166","id":"p4-b09-007","paper":4,"order":4380},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What are the main components of an HVAC system assessed in a performance test?","back":"(1) Chiller plant: evaporator; compressor (VCR) or absorber and generator (VAR); condenser with condenser or cooling tower fans. (2) Air handling unit with fans or blowers. (3) Primary and secondary chilled/cooling water pumps.","explain":"A performance test covers every part of the system, not just the chiller. Pump and fan power is part of the total energy use of the plant.","flash":false,"source":"BEE Book 4 Ch 09 p166","id":"p4-b09-008","paper":4,"order":4381},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How should a VCR performance test be taken: how many data sets, at what interval, and in what condition?","back":"Establish steady-state conditions first, then take three sets of data, preferably at least five minutes apart. Take readings simultaneously across all components, as far as possible.","explain":"Transient conditions distort the energy balance, so readings are taken in steady operation. Simultaneous readings keep the evaporator, compressor and condenser data consistent with each other.","flash":false,"source":"BEE Book 4 Ch 09 p166","id":"p4-b09-009","paper":4,"order":4382},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What two measurements are needed to find the net refrigeration capacity at the evaporator?","back":"The chilled water flow rate through the evaporator, and the chilled water inlet and outlet temperatures. Heat removed = flow × temperature difference × specific heat of water.","explain":"Temperature readings must have a least count of at least 0.1 °C because the temperature difference across the evaporator is small. Net refrigeration capacity in TR = m × Cp × (t_in - t_out) / 3024.","flash":false,"source":"BEE Book 4 Ch 09 p166","id":"p4-b09-010","paper":4,"order":4383},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How can chilled water flow be measured when there is no online flow meter?","back":"(1) If hot and cold wells exist, from the tank level dip or rise after switching off the secondary pump. (2) Non-invasively, with a well-calibrated ultrasonic flow meter. (3) If waterside pressure drops are close to design values, assume pump flow equals design rated flow.","explain":"The tank-level method measures the actual flow directly. The ultrasonic method does not disturb the system. The pressure-drop method is only an approximation and holds only when the drops are near design values.","flash":false,"source":"BEE Book 4 Ch 09 p167","id":"p4-b09-011","paper":4,"order":4384},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is the compressor power found in a performance test?","back":"Read it directly in kW if the meter shows kW. If not, measure current with an ammeter or tong tester, then calculate power = √3 × voltage × current × power factor (kW).","explain":"Current, voltage and power factor can all be measured in the field, so compressor input can be found without a kW meter. The √3 factor is for three-phase supply.","flash":false,"source":"BEE Book 4 Ch 09 p167","id":"p4-b09-012","paper":4,"order":4385},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is the heat rejected at the condenser calculated, in TR?","back":"Heat rejected = cooling load + work done by the compressor. In TR: heat rejected (TR) = evaporator TR + compressor shaft power (kW) / 3.516.","explain":"The condenser must reject the heat taken from the chilled water plus the heat equivalent of the compressor's work. Shaft power is the power absorbed by the compressor, derived from the motor measurement.","flash":true,"source":"BEE Book 4 Ch 09 p167","id":"p4-b09-013","paper":4,"order":4386},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is heat rejected at a water-cooled condenser measured?","back":"Measure the cooling water flow with a flow meter and the inlet and outlet water temperatures with a digital thermometer. Heat rejected (TR) = Mc × Cp × (t_wo - t_wi) / 3024, with Mc in kg/h and Cp in kcal/kg °C.","explain":"This is the same sensible-heat balance used on the chilled water side, applied to the cooling water. Mass flow is needed, so a flow meter is essential.","flash":false,"source":"BEE Book 4 Ch 09 p167","id":"p4-b09-014","paper":4,"order":4387},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is heat rejected at an air-cooled condenser measured, and why is only sensible heat counted?","back":"Measure the air flow across the condenser coil and the air inlet and outlet temperatures. Heat rejected (TR) = Ma × Cpa × (t_ao - t_ai) / 3024. Only sensible heat is counted because the air-side process is normally sensible heating.","explain":"The air warms without a change of moisture, so the temperature rise carries all the heat. Ma is the mass flow of air in kg/h.","flash":false,"source":"BEE Book 4 Ch 09 p168","id":"p4-b09-015","paper":4,"order":4388},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What instruments measure air flow in the test, and what least count is required for the anemometer?","back":"A vane anemometer or a hot-wire anemometer, both duly calibrated, with a least count of 0.1 m/s. Air flow = average air velocity in the plane of measurement × flow area.","explain":"The average velocity is taken across the face area, as in Example 3 where readings were taken at several locations. The flow result is only as good as the velocity reading.","flash":false,"source":"BEE Book 4 Ch 09 p168","id":"p4-b09-016","paper":4,"order":4389},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What three ratios express the energy efficiency of a chiller, and which one is calculated first?","back":"COP = kW refrigeration effect / kW input; EER = W refrigeration effect / W input; kW/ton = kW input / tons refrigeration effect. kW/ton is calculated first from the measured parameters; the other two follow from it.","explain":"The book states that COP and EER come out numerically the same when units are consistent. EER is a performance indicator only for window, split and package air conditioners.","flash":false,"source":"BEE Book 4 Ch 09 p168","id":"p4-b09-017","paper":4,"order":4390},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"Which equipment does the book say EER is used as a performance indicator for?","back":"Only window, split and package air conditioners.","explain":"The book notes that smaller chillers and rooftop units are often measured in EER, but limits EER as a performance indicator to window, split and package air conditioners. Chiller performance is assessed on kW/TR and COP.","flash":false,"source":"BEE Book 4 Ch 09 p169","id":"p4-b09-018","paper":4,"order":4391},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is the heat load of an air handling unit calculated, and what does a difference from the theoretical load indicate?","back":"Heat load (TR) = m × (h_in - h_out) / (4.18 × 3024), with m in kg/h and enthalpies in kJ/kg read from a psychrometric chart. A difference from the theoretical load shows leakages, unwanted loads and heat ingress.","explain":"The field figure comes from measured airflow and the enthalpy change across the AHU. The theoretical figure sums the sensible and latent loads of the room from standard handbooks. The difference is the loss to investigate.","flash":false,"source":"BEE Book 4 Ch 09 p169","id":"p4-b09-019","paper":4,"order":4392},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What readings are taken to evaluate a fan or blower?","back":"Air flow rate; static pressure (differential head) by pitot tube and manometer; RPM by tachometer or stroboscope; and power by power analyser. Compare with design parameters.","explain":"These readings establish the fan's actual performance, which is then compared with the design performance.","flash":false,"source":"BEE Book 4 Ch 09 p169","id":"p4-b09-020","paper":4,"order":4393},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What readings are taken to evaluate primary and secondary water pumps?","back":"Water flow rate; head developed (from suction and discharge pressure gauges); RPM; and current, voltage and power drawn by the motor (kW). Compare with the pump performance chart or design parameter.","explain":"Head is the pressure difference between discharge and suction gauges. Measuring power at the motor allows pump-set performance to be compared with the chart.","flash":false,"source":"BEE Book 4 Ch 09 p169","id":"p4-b09-021","paper":4,"order":4394},
{"kind":"problem","topic":"HVAC Performance Evaluation","front":"A chilled water system in a chemical plant has chilled water flow 165 m³/h, evaporator inlet 8.8 °C and outlet 7.2 °C. Compressor motor input is 112 kW at 92% motor efficiency. Find the net refrigeration capacity, kW/TR and COP.","back":"Net refrigeration capacity = 87.3 TR; kW/TR = 1.18; COP = 2.98.","explain":"This is the book's first worked example. Pump powers and compressor circuit loadings are recorded in the data but are not used in this compressor-only calculation.","flash":false,"source":"BEE Book 4 Ch 09 p170","steps":[{"prompt":"Convert the chilled water flow to kg/h and find the net refrigeration capacity.","answer":"165 m³/h × 1000 kg/m³ = 165,000 kg/h; TR = 165,000 × 1 × (8.8 - 7.2) / 3024 = 87.3 TR.","explain":"Water density is 1000 kg/m³ and Cp is 1 kcal/kg °C, so the mass flow times the temperature difference gives kcal/h; dividing by 3024 gives TR."},{"prompt":"Find the compressor power.","answer":"112 kW × 0.92 (motor efficiency) = 103 kW.","explain":"The book takes compressor power as motor input times motor efficiency."},{"prompt":"Calculate kW/TR.","answer":"103 / 87.3 = 1.18 kW/TR.","explain":"Lower kW/TR means a more efficient chiller."},{"prompt":"Calculate COP.","answer":"COP = (87.3 × 3024) / (103 × 860) = 2.98.","explain":"Both sides are converted to kcal/h: 1 TR = 3024 kcal/h and 1 kW = 860 kcal/h."}],"id":"p4-b09-022","paper":4,"order":4395},
{"kind":"problem","topic":"HVAC Performance Evaluation","front":"An office air conditioner has a direct-expansion AHU with air flow 22,237 m³/h at density 1.29 kg/m³, enthalpy 59.85 kJ/kg in and 45.82 kJ/kg out. Motor input is 35 kW at 91% efficiency, direct driven. Find the refrigeration effect, TR, compressor shaft power, EER and specific power consumption.","back":"Refrigeration effect = 402,461 kJ/h (about 111.8 kW, about 31.8 TR); shaft power = 31.9 kW; EER = 3.5; SPC = about 1.0 kW/TR.","explain":"Example 2 of the chapter. The book compares these actual values with design values; any deviation calls for further analysis of the equipment.","flash":false,"source":"BEE Book 4 Ch 09 p171","steps":[{"prompt":"Find the mass flow of air.","answer":"22,237 m³/h × 1.29 kg/m³ = 28,686 kg/h.","explain":"Volume flow is converted to mass flow using air density."},{"prompt":"Find the refrigeration effect in kJ/h.","answer":"28,686 × (59.85 - 45.82) = 402,461 kJ/h, about 111.8 kW.","explain":"The enthalpy drop across the coil gives the heat removed from the air. 1 kW = 3600 kJ/h."},{"prompt":"Convert to TR.","answer":"402,461 / (3.516 × 3600) = about 31.8 TR (the book shows 31.85).","explain":"1 TR = 3.516 kW, so 111.8 / 3.516 is about 31.8 TR."},{"prompt":"Find compressor shaft power.","answer":"35 kW × 0.91 (motor) × 1.00 (direct drive) = 31.9 kW.","explain":"Motor input times motor efficiency gives shaft power; direct drive transmission efficiency is 100%."},{"prompt":"Find EER and specific power consumption.","answer":"EER = 111,800 W / 31,900 W = 3.5; SPC = 31.9 kW / 31.8 TR = about 1.0 kW/TR.","explain":"EER is watts of cooling over watts of input; SPC is kW per TR."}],"id":"p4-b09-023","paper":4,"order":4396},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is the compressor shaft power estimated from the measured motor input?","back":"Shaft power = motor input power × motor efficiency × drive transmission efficiency (100% for a direct-driven compressor).","explain":"This converts electrical motor input into the mechanical power the compressor receives. With direct drive the drive efficiency is 100%, so only motor efficiency reduces the power.","flash":false,"source":"BEE Book 4 Ch 09 p171","id":"p4-b09-024","paper":4,"order":4397},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"What must be ensured about the evaporator, condenser and generator during a VAR test?","back":"They must be at nearly the same operating conditions throughout the test. Auxiliaries (chilled water pumps, condenser water pumps, cooling tower fans) are assessed the same way as for a VCR system.","explain":"Keeping the three vessels at steady conditions makes the heat balance valid over the test period. Because the auxiliaries follow the VCR method, the same flow and power readings apply.","flash":false,"source":"BEE Book 4 Ch 09 p172","id":"p4-b09-025","paper":4,"order":4398},
{"kind":"problem","topic":"HVAC Performance Evaluation","front":"An AHU has a face area of 1.19 m² and average air velocity 1.3 m/s. Inlet air is 29.4 °C dry bulb and 24.4 °C wet bulb; outlet is 24.4 °C dry bulb and 19.2 °C wet bulb. Air density is 1.2 kg/m³. Find the air flow, mass flow, enthalpies and heat load in TR.","back":"Air flow = 5,569 m³/h; mass flow = 6,683 kg/h; enthalpy 73.34 kJ/kg in and 54.5 kJ/kg out; heat load = about 10 TR.","explain":"Example 3 of the chapter. The enthalpies are read from the psychrometric chart using the dry and wet bulb readings.","flash":false,"source":"BEE Book 4 Ch 09 p172","steps":[{"prompt":"Find the air flow rate.","answer":"1.19 m² × 1.3 m/s × 3600 = 5,569 m³/h.","explain":"Average velocity times face area gives m³/s; multiplying by 3600 gives m³/h."},{"prompt":"Find the mass flow rate.","answer":"5,569 × 1.2 = 6,683 kg/h.","explain":"The book assumes air density of 1.2 kg/m³."},{"prompt":"Read the enthalpies from the psychrometric chart.","answer":"Inlet 73.34 kJ/kg; outlet 54.5 kJ/kg.","explain":"Each dry and wet bulb pair fixes one point on the chart."},{"prompt":"Calculate the heat load.","answer":"6,683 × (73.34 - 54.5) / (4.18 × 3024) = about 10 TR.","explain":"Dividing by 4.18 converts kJ/kg to kcal/kg; 3024 kcal/h equals 1 TR."}],"id":"p4-b09-026","paper":4,"order":4399},
{"kind":"fact","topic":"HVAC Performance Evaluation","front":"How is the thermal energy input of a VAR chiller measured, for steam-heated and fuel-fired packages?","back":"Steam: a calibrated in-line steam flow meter, or collect condensate in a calibrated container over a timed period (stopwatch reading to 1/100 s), cooling the condensate to reduce flash steam losses. Fuel: a calibrated in-line fuel flow meter, or the fuel level drop in a calibrated day tank over a timed period.","explain":"Thermal input is the energy the chiller consumes, so the steam or fuel flow must be measured accurately. Cooling the condensate reduces flash steam losses, which would otherwise under-read the flow.","flash":false,"source":"BEE Book 4 Ch 09 p173","id":"p4-b09-027","paper":4,"order":4400}
]$cards$::jsonb);
